package com.huy.enterprise.company;
import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.RecordStatus; import com.huy.enterprise.user.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class EmployeeService{private final EmployeeRepository repository;private final CompanyRepository companies;private final DepartmentRepository departments;private final UserRepository users;public List<EmployeeResponse> all(){return repository.findAll().stream().map(EmployeeResponse::from).toList();}@Transactional public EmployeeResponse create(EmployeeRequest r){if(repository.existsByEmployeeCode(r.employeeCode()))throw new ConflictException("Employee code already exists: "+r.employeeCode());Employee e=new Employee();e.setEmployeeCode(r.employeeCode());apply(e,r);return EmployeeResponse.from(repository.save(e));}@Transactional public EmployeeResponse update(UUID id,EmployeeRequest r){Employee e=get(id);if(!e.getEmployeeCode().equals(r.employeeCode())&&repository.existsByEmployeeCode(r.employeeCode()))throw new ConflictException("Employee code already exists: "+r.employeeCode());e.setEmployeeCode(r.employeeCode());apply(e,r);return EmployeeResponse.from(repository.save(e));}private Employee get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Employee not found: "+id));}private void apply(Employee e,EmployeeRequest r){Company c=companies.findById(r.companyId()).orElseThrow(()->new ResourceNotFoundException("Company not found: "+r.companyId()));Department d=r.departmentId()==null?null:departments.findById(r.departmentId()).orElseThrow(()->new ResourceNotFoundException("Department not found: "+r.departmentId()));if(d!=null&&!d.getCompany().getId().equals(c.getId()))throw new BusinessException("Department does not belong to selected company");e.setCompany(c);e.setDepartment(d);e.setUser(r.userId()==null?null:users.findById(r.userId()).orElseThrow(()->new ResourceNotFoundException("User not found: "+r.userId())));e.setFullName(r.fullName());e.setEmail(r.email());e.setPhone(r.phone());e.setJobTitle(r.jobTitle());e.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());}}
